const store = createSetupStore(({ ref, computed }) => {
  const count = ref(0)
  const double = computed(() => count.value * 2)
  function inc() { this.count += 1 }
  return { count, double, inc }
})
store.inc()
store.double   // 2
store.$patch({ count: 10 })
store.$reset()  // count 回到 0

const router = createRouter({ routes: [{ name: 'about', path: '/about' }], mode: 'history', base: '/app' })
router.resolve('/about').name   // 'about'
router.history.toUrl('/about')  // '/app/about'
runGuards([() => false], '/admin', '/')  // { type: 'abort' }

