{
  check('signal 可读可写，写同值不算变化', () => {
    const g = createGraph()
    const a = g.signal(1)
    same(g.read(a), 1)
    same(g.set(a, 1), false, '同值写入不该触发更新')
    same(g.set(a, 2), true)
